import type { ReactNode } from 'react'

/** Claude and Codex brand paths. Attribution and upstream license: ../../NOTICE.md. */
interface MarkProps {
  className?: string
}

/**
 * Both glyphs retain their original 100 × 100 frame and inherit the surrounding text colour.
 */
function Mark({
  className,
  children,
  viewBox = '0 0 100 100',
}: MarkProps & { children: ReactNode; viewBox?: string }) {
  return (
    <svg
      viewBox={viewBox}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      focusable="false"
      className={className}
    >
      {children}
    </svg>
  )
}

